// exe FUN_009be6c0 → FUN_008a56f0: every warcry but Call of Blood gives the caster's army FUN_009bdbd0's rage points.
if (id != "SPELL_WARCRY_CALL_OF_BLOOD")
{
    int armyRp = WarcryRagePoints(id, hero);
    foreach (var u in S.LivingOf(side).Where(u => u.Has(Ab.DemonRaged)).ToList()) AddRage(u, armyRp);
}

sp += RoadHomeSpeedBonus(u);   // Familiar Ground (exe FUN_008a0e30)
if (u.HasEffect(H5.Combat.Fx.Battlecry)) sp += Stats.Get("combat/Spells/Warcries/Battlecry_SpeedBonus/Base", 1);
sp += RageBonus(u, "DEMON_RAGE_BONUS_SPEED");
var eh = Enemy(u.Side);
// Storm Wind slows enemy flyers by StormWind_SpeedPenalty; results below 2 become 1 (exe 008a1e50).
if (eh.Present && u.Flying && (eh.HasPerk(Sk.StormWind) || eh.HasPerk(Sk.BarbStormWind)))
{
    sp -= Stats.Get("combat/HeroSkills/Ranger/StormWind_SpeedPenalty", 2);
    if (sp < 2) sp = 1;
}
if (eh.Present && Specials.Pieces(eh, Specials.Necromancers) >= 2) sp -= (int)Stats.Get("ArtifactsSetsEffectsConsts/Necromancers_2_EnemyCreature_DeSpeed", 1);
if (u.HasEffect(H5.Combat.Fx.RuneCharge)) sp *= 2;
if (u.HasEffect(H5.Combat.Fx.Wound)) sp *= 1 - Stats.Get("combat/Creatures/Fortress/Wound_SpeedDecrease", 0.4);
return Math.Max(1, (int)Math.Floor(sp));

sp += RoadHomeSpeedBonus(u);   // Familiar Ground (exe FUN_008a0e30)
// exe FUN_008a1e50 order: Wound trunc((1 − clamp(dec, 0, 1))·speed) → enemy Storm Wind on flyers → Rune of Charge ×2
// → enemy Necromancers set → Demon Rage speed bonus → Battlecry ((level−1)/div·per + base); clamped at 0.
if (u.HasEffect(H5.Combat.Fx.Wound))
    sp = Math.Floor((1 - Math.Clamp((double)(float)Stats.Get("combat/Creatures/Fortress/Wound_SpeedDecrease", 0.4), 0, 1)) * sp);
var eh = Enemy(u.Side);
// Storm Wind slows enemy flyers by StormWind_SpeedPenalty; results below 2 become 1 (exe 008a1e50).
if (eh.Present && u.Flying && (eh.HasPerk(Sk.StormWind) || eh.HasPerk(Sk.BarbStormWind)))
{
    sp -= Stats.Get("combat/HeroSkills/Ranger/StormWind_SpeedPenalty", 2);
    if (sp < 2) sp = 1;
}
if (u.HasEffect(H5.Combat.Fx.RuneCharge)) sp *= 2;
if (eh.Present && Specials.Pieces(eh, Specials.Necromancers) >= 2) sp -= (int)Stats.Get("ArtifactsSetsEffectsConsts/Necromancers_2_EnemyCreature_DeSpeed", 1);
sp += RageBonus(u, "DEMON_RAGE_BONUS_SPEED");
if (u.GetEffect(H5.Combat.Fx.Battlecry) is { } battlecry) sp += battlecry.Value2;
return Math.Max(0, (int)Math.Floor(sp));

if (melee && !retaliation && HasAbilityNow(a, Ab.Bash) && !t.Has(Ab.Mechanical) && !t.IsWarMachine
    && ProcRoll(a, t, Stats.Get("combat/Creatures/Haven/Bash_ProcFactor", 1.5), primaryHpBefore, soldiersLuckDoubles: true, secondRoll: false))
{
    Emit(new AbilityTriggered(a.Id, Ab.Bash, t.Id));
    SetAtb(t.Id, 0);
    stunned = true;
    RageEvent(t, "ReceiveBashRP");
}

// Rune of Stunning shares Bash's single chance and immunity (exe FUN_00a59a90 / FUN_00a5d370): Bash_ProcFactor,
// never against MECHANICAL; Bash only off retaliation and in melee, the rune on any strike.
bool thunderclap = a.HasEffect(H5.Combat.Fx.RuneThunderclap);
if ((thunderclap || melee && !retaliation && HasAbilityNow(a, Ab.Bash)) && !t.Has(Ab.Mechanical) && !t.IsWarMachine
    && ProcRoll(a, t, Stats.Get("combat/Creatures/Haven/Bash_ProcFactor", 1.5), primaryHpBefore, soldiersLuckDoubles: true, secondRoll: false))
{
    Emit(new AbilityTriggered(a.Id, thunderclap ? "RUNE_THUNDERCLAP" : Ab.Bash, t.Id));
    SetAtb(t.Id, 0);
    stunned = true;
    if (thunderclap) RemoveEffect(a, H5.Combat.Fx.RuneThunderclap);
    else RageEvent(t, "ReceiveBashRP");
}

if (a.HasEffect(H5.Combat.Fx.RuneThunderclap) && RollProc(a, ProcChance(a, t, 1, primaryHpBefore)))
{
    Emit(new AbilityTriggered(a.Id, "RUNE_THUNDERCLAP", t.Id));
    SetAtb(t.Id, 0);
    RemoveEffect(a, H5.Combat.Fx.RuneThunderclap);
}
